\section*{End Matter}


The goal of this End Matter is to present a simple argument that
yields the scaling exponents of the CMI $I(A:C|B)$ given in Eqs.~\eqref{Eq:large_y_regime_a}--\eqref{Eq:large_y_regime_c} in the main text, for a Gaussian distribution $P[\phi] \propto \exp[-\frac{1}{2}\sum_{i,j}\phi_i K_{i,j}\phi_j]$.
While we restrict ourselves to a system
partitioned into $A\cup B\cup C$ with the annular geometry in Fig.~\ref{fig:geometries}(a), the same argument extends naturally to other geometries. 
We therefore think it is valuable to present the simple argument here.

The CMI for a Gaussian distribution has been implicitly developed in Refs.~\cite{gelfand1959calculation,bach2002kernel,gretton2005kernel,barnett2009granger} and takes the form
\begin{equation}
\label{Eq:gaussian_cmi_trace_log}
\begin{aligned}
I(A:C|B)
&=-\frac{1}{2}\Tr\log(1-{\cal T})=\frac{1}{2}\sum_{m=1}^{\infty}\frac{1}{m}\Tr({\cal T}^m),\\
{\cal T}& \equiv
K_A^{-1}K_{A,C}K_C^{-1}K_{C,A}.
\end{aligned}
\end{equation}
Here, $K_X \equiv K_{X,X}$ is the diagonal block of the quadratic kernel $K$, while $K_{A,C}$ denotes the off-diagonal block of $K$.
In the continuum limit, one has
\begin{equation}
\label{Eq:bridge_continuum}
\begin{aligned}
  {\cal T}(\mathbf a,\mathbf a')& =\int_A d^d x\int_C d^d c\,d^d c'  \\
 & K_A^{-1}(\mathbf a,\mathbf x) 
  K_{A,C}(\mathbf x,\mathbf c)
K_C^{-1}(\mathbf c,\mathbf c')K_{C,A}(\mathbf c',\mathbf a').
\end{aligned}
\end{equation}



Recall that we consider the scenario where $K$ can be decomposed into a local scale-invariant part $K^{\rm loc}$ with $K^{\rm loc}(\lambda\mathbf q)=\lambda^{h_{\rm loc}}K^{\rm loc}(\mathbf q)$ and an irrelevant nonlocal part with $K^{\rm nloc}(\lambda\mathbf q)=\lambda^{h_{\rm nloc}}K^{\rm nloc}(\mathbf q)$, i.e.,
\begin{equation}
\label{Eq:precision_two_term_appendix}
\begin{aligned}
K(\mathbf q;\xi_{\rm cross})
&=K^{\rm loc}(\mathbf q)+\xi_{\rm cross}^{|\omega|}K^{\rm nloc}(\mathbf q),\end{aligned}
\end{equation}
where $\omega =h_{\rm loc}-h_{\rm nloc} = -|\omega|<0
$ so that the nonlocal part is irrelevant. 
This implies that  the local part dominates at lengths much
larger than $\xi_{\rm cross}$, whereas the nonlocal part dominates at lengths
much smaller than $\xi_{\rm cross}$.
In the following, we assume that the dominant part has a
well-defined restricted inverse and that the continuum integrals below converge.

In the $l_B \gg l$ limit, the leading term in Eq.~\eqref{Eq:gaussian_cmi_trace_log} is
\begin{equation}
\label{Eq:gaussian_cmi_large_y_leading}
\begin{aligned}
I(A:C|B)
&=\frac12\Tr\!\left[K_A^{-1}K_{A,C}K_C^{-1}K_{C,A}\right]+O\!\left(\Tr\mathcal T^2\right).
\end{aligned}
\end{equation}
Since local interactions do not contribute
to $K_{A,C}$ or $K_{C,A}$, only 
$\xi_{\rm cross}^{|\omega|}K^{\rm nloc}$ contributes to both of them.
Therefore, 
\begin{equation}
\label{Eq:large_y_explicit}
\begin{aligned}
&I(A:C|B)=\frac{\xi_{\rm cross}^{2|\omega|}}{2}
\int_A d^d a\,d^d a'\int_C d^d c\,d^d c'\\
&
K_A^{-1}(\mathbf a,\mathbf a';\xi_{\rm cross})
K^{\rm nloc}(\mathbf a'-\mathbf c)
K_C^{-1}(\mathbf c,\mathbf c';\xi_{\rm cross})
K^{\rm nloc}(\mathbf c'-\mathbf a),
\end{aligned}
\end{equation}
up to an $O(\Tr\mathcal T^2)$ correction.



The CMI scaling can now be deduced by simple counting of the length factors in the integral of Eq.\eqref{Eq:large_y_explicit}.
Let us first consider the part that is independent of $\xi_{\rm cross}$, i.e., $\int_A d^d a d^d a'$, $\int_C d^d c\,d^d c'$, $K^{\rm nloc}(\mathbf a'-\mathbf c)$,  and $K^{\rm nloc}(\mathbf c'-\mathbf a)$. 
The two integrations over
$A$ supply $l^{2d}$, and measuring the two coordinates in $C$ in units of
$l_B$ supplies $l_B^{2d}$. 
On the other hand, to determine the length scale each nonlocal kernel supplies, we recall that $K(\mathbf r)\sim \int {d^d q}e^{i\mathbf q\cdot\mathbf r}K(\mathbf q)$, and thus 
\begin{equation}
K^{\rm loc/nloc}(\lambda\mathbf r)
=\lambda^{-d-h_{\rm loc/nloc}}K^{\rm loc/nloc}(\mathbf r).
\end{equation}
This implies each nonlocal kernel supplies
$l_B^{-(d+h_{\rm nloc})}$.
More concretely, 
at fixed $\mathbf c/l_B$, one has 
\begin{equation}
\begin{aligned}
K^{\rm nloc}(\mathbf a'-\mathbf c)
&=l_B^{-(d+h_{\rm nloc})}
K^{\rm nloc}\!\left(-\frac{\mathbf c}{l_B}+\frac{\mathbf a'}{l_B}\right)\\
&=l_B^{-(d+h_{\rm nloc})}
\left[K^{\rm nloc}\!\left(-\frac{\mathbf c}{l_B}\right)
+O\!\left(\frac{l}{l_B}\right)\right].
\end{aligned}
\end{equation}
The same argument applies to $K^{\rm nloc}(\mathbf c'-\mathbf a)$.
Therefore, to leading order in $l/l_B$, both kernels are independent of the coordinates within $A$.
As a consequence, apart from $K_A^{-1}$ and $K_C^{-1}$, the length dependence is
\begin{equation}
\label{Eq:large_y_powers}
\xi_{\rm cross}^{2|\omega|}\ 
l^{2d}\ l_B^{2d} \ 
{l_B^{-2(d+h_{\rm nloc})}}= \xi_{\rm cross}^{2|\omega|}\ 
{l^{2d}}\ 
{l_B^{-2 h_{\rm nloc}}}.
\end{equation}

On the other hand, the length dependences of $K_A^{-1}$ and $K_C^{-1}$ depend on whichever
part of the kernel dominates at the relevant length. 
To find their scaling, we note that the restricted  inverse is defined by
$\int_X d^d x\,K(\mathbf r-\mathbf x;\xi_{\rm cross})K_X^{-1}(\mathbf x,\mathbf r';\xi_{\rm cross})=\delta^d(\mathbf r-\mathbf r')$
for $\mathbf r,\mathbf r'\in X$. 
Together with the scaling of $K$, i.e., $K(\lambda\mathbf r;\lambda\xi_{\rm cross})
=\lambda^{-d-h_{\rm loc}}K(\mathbf r;\xi_{\rm cross})$, this gives
\begin{equation}
\label{Eq:restricted_inverse_scaling}
\begin{aligned}
&\left(K_{\lambda X}^{-1}\right)
(\lambda\mathbf r,\lambda\mathbf r';\lambda\xi_{\rm cross})=\lambda^{h_{\rm loc}-d}
\left(K_X^{-1}\right)(\mathbf r,\mathbf r';\xi_{\rm cross}).
\end{aligned}
\end{equation}
In the local regime the inverse has spatial degree $h_{\rm loc}-d$.
In the nonlocal regime,
$K_X^{-1}\simeq\xi_{\rm cross}^{-|\omega|}(K_X^{\rm nloc})^{-1}$,
so its spatial degree is $h_{\rm nloc}-d$.  
It follows that
\begin{equation}
\label{Eq:restricted_inverse_regimes}
\begin{aligned}
K_A^{-1}&\sim
\begin{cases}
l^{h_{\rm loc}-d},&\xi_{\rm cross}\ll l,\\
\xi_{\rm cross}^{-|\omega|}l^{h_{\rm nloc}-d},&l\ll\xi_{\rm cross},
\end{cases}\\[3pt]
K_C^{-1}&\sim
\begin{cases}
l_B^{h_{\rm loc}-d},&\xi_{\rm cross}\ll l_B,\\
\xi_{\rm cross}^{-|\omega|}l_B^{h_{\rm nloc}-d},&l_B\ll\xi_{\rm cross}.
\end{cases}
\end{aligned}
\end{equation}
Here $\sim$ suppresses dimensionless coordinate dependence and shape factors.
Combining Eq.~\eqref{Eq:large_y_powers} with the two inverse factors in
Eq.~\eqref{Eq:restricted_inverse_regimes}, one finds:

\begin{enumerate}[(i)]
\item When $\xi_{\rm cross}\ll l\ll l_B$, the local part controls both
restricted inverses. Hence (recall $\omega =h_{\rm loc}-h_{\rm nloc} = -|\omega|$)
\begin{equation}
\label{Eq:large_y_regime_a_appendix}
\begin{aligned}
I(A:C|B)
&\sim (\xi_{\rm cross}^{2|\omega|}\ 
{l^{2d}}\ 
{l_B^{-2 h_{\rm nloc}}}) (l^{h_{\rm loc}-d}\ l_B^{h_{\rm loc}-d})\\
&=\left(\frac{\xi_{\rm cross}}{l_B}\right)^{2|\omega|}
\left(\frac{l}{l_B}\right)^{d+h_{\rm loc}}.
\end{aligned}
\end{equation}
\item When $l\ll\xi_{\rm cross}\ll l_B$, the nonlocal part controls
$K_A^{-1}$, while the local part still controls $K_C^{-1}$.
We therefore find that 
\begin{equation}
\label{Eq:large_y_regime_b_appendix}
\begin{aligned}
I(A:C|B) & \sim  (\xi_{\rm cross}^{2|\omega|}\ 
{l^{2d}}\ 
{l_B^{-2 h_{\rm nloc}}})(\xi_{\rm cross}^{-|\omega|}l^{h_{\rm nloc}-d} l_B^{h_{\rm loc}-d}) \\
&=
\left(\frac{\xi_{\rm cross}}{l_B}\right)^{|\omega|}
\left(\frac{l}{l_B}\right)^{d+h_{\rm nloc}}.
\end{aligned}
\end{equation}
\item When $l\ll l_B\ll\xi_{\rm cross}$, the nonlocal part controls both
restricted inverses at the relevant distances, and thus
\begin{equation}
  \begin{aligned}
\label{Eq:large_y_regime_c_appendix}
I(A:C|B) & \sim  (\xi_{\rm cross}^{2|\omega|}\ 
{l^{2d}}\ 
{l_B^{-2 h_{\rm nloc}}})(\xi_{\rm cross}^{-2|\omega|}l^{h_{\rm nloc}-d} l_B^{h_{\rm nloc}-d}) \\
& =
\left(\frac{l}{l_B}\right)^{d+h_{\rm nloc}}.
\end{aligned}
\end{equation}
\end{enumerate}


