\section{Derivation of Eq.~\eqref{Eq:cmi_susceptibility} in the main text}
\label{app:perturbative_cmi}

The goal of this appendix is to provide more details on how the CMI to {leading (second) order} in $\epsilon$ for perturbed Langevin dynamics, i.e., Eq.~\eqref{Eq:cmi_susceptibility} in the main text, is obtained.
It is essentially a direct combination of the existing quadratic expansion of the CMI around a classical Markov distribution~\cite{kullback1962tests,kubkowski2021power} with the first-order McLennan--Zubarev expression for the steady state~\cite{mclennan1959statistical,zubarev1974nonequilibrium,maes2010rigorous}, both of which we briefly rederive using notation consistent with the main text. 


\paragraph*{Perturbative CMI identity}

Let $P_0$ be Markov, i.e., $P_0[\phi]=P_0[\phi_A,\phi_B]P_0[\phi_B,\phi_C]/P_0[\phi_B]$, for the regions in Fig.~\ref{fig:geometries}(a), and perturb it as
\begin{equation}
\label{Eq:perturbed_state}
P_\epsilon[\phi]=P_0[\phi]\left[1+\epsilon V[\phi]+O(\epsilon^2)\right].
\end{equation}
Here $\epsilon V$ is the first-order relative correction to $P_0$. Probability conservation implies $\langle V\rangle_0=0$, where $\langle\cdot\rangle_0$ denotes the average over $P_0$.
To compute the corresponding CMI at leading order in $\epsilon$, it's useful to note that, for any classical distribution $P$, the CMI can be equivalently written as the relative entropy
\begin{equation}
\label{Eq:cmi_relative_entropy}
\begin{aligned}
I(A:C|B)&=D(P\|Q)=\int\mathcal D\phi\,P[\phi]\log\frac{P[\phi]}{Q[\phi]},\quad
Q[\phi]=\frac{P[\phi_A,\phi_B]\,P[\phi_B,\phi_C]}{P[\phi_B]}.
\end{aligned}
\end{equation}
Eq.~\eqref{Eq:cmi_relative_entropy} makes it apparent that the CMI measures how far $P$ is from the conditionally independent distribution built from its own marginals.
These marginals can be computed perturbatively as
\begin{equation}
\label{Eq:marginal_expansion}
\begin{aligned}
P_\epsilon[\phi_A,\phi_B]&=\int\mathcal D\phi_C\,P_\epsilon[\phi]=P_0[\phi_A,\phi_B]\left[1+\epsilon\langle V\rangle_{0|AB}\right]+O(\epsilon^2),
\end{aligned}
\end{equation}
where for any region $X$ with complement $\bar X$, we let $V_X[\phi_X]\equiv\langle V\rangle_{0|X}[\phi_X]=\int\mathcal D\phi_{\bar X}\,P_0[\phi_{\bar X}|\phi_X]\,V[\phi]$ denote the conditional average at fixed $\phi_X$. 
The analogous expressions hold for the other two marginals.
Writing $V_{AB}\equiv\langle V\rangle_{0|AB}$, and likewise $V_{BC}$ and $V_B$ for the other two marginals, we have $P_\epsilon[\phi_B,\phi_C]=P_0[\phi_B,\phi_C](1+\epsilon V_{BC})+O(\epsilon^2)$ and $P_\epsilon[\phi_B]=P_0[\phi_B](1+\epsilon V_{B})+O(\epsilon^2)$.

Inserting these into Eq.~\eqref{Eq:cmi_relative_entropy}, one finds $Q_\epsilon = P_0[1+\epsilon(V_{AB}+V_{BC}-V_B)]+O(\epsilon^2)$.  Subtracting this from $P_\epsilon$ gives
\begin{equation}
\label{Eq:residual}
P_\epsilon=Q_\epsilon + \epsilon\, P_0\, V_\times+O(\epsilon^2),\qquad
V_\times=V-V_{AB}-V_{BC}+V_{B}.
\end{equation}
It remains to expand the relative entropy in Eq.~\eqref{Eq:cmi_relative_entropy}. Letting $\delta_\epsilon\equiv P_\epsilon-Q_\epsilon$, one has
\begin{equation}
\log\frac{P_\epsilon}{Q_\epsilon}
=\log\left(1+\frac{\delta_\epsilon}{Q_\epsilon}\right)
=\frac{\delta_\epsilon}{Q_\epsilon}-\frac{\delta_\epsilon^2}{2Q_\epsilon^2}+O(\epsilon^3).
\end{equation}  
Multiplying by $P_\epsilon=Q_\epsilon+\delta_\epsilon$, retaining
terms through second order, and using
$\int\mathcal D\phi\,\delta_\epsilon=0$ (since both distributions
are normalized), we find  
\begin{equation}
\label{Eq:perturbative_cmi}
\begin{aligned}
I_\epsilon(A:C|B)=D(P_\epsilon\|Q_\epsilon)
&=\frac{1}{2}\int\mathcal D\phi\,\frac{\delta_\epsilon^2}{Q_\epsilon}+O(\epsilon^3)=\frac{\epsilon^2}{2}\,\langle V_\times^2\rangle_0+O(\epsilon^3).
\end{aligned}
\end{equation}

\paragraph*{First-order correction to the Langevin steady state}

We now derive the first-order McLennan--Zubarev expression for the steady state~\cite{mclennan1959statistical,zubarev1974nonequilibrium,maes2010rigorous}.
We consider Langevin dynamics with an added term in the deterministic part of the dynamics that need not be the gradient of any potential, so that detailed balance is broken. 
Let $\phi_i$ denote the field variables and take
\begin{equation}
\label{Eq:langevin_appendix}
\dot\phi_i=-\frac{\partial H}{\partial\phi_i}+\epsilon\, v_i(\phi)+\zeta_i,
\end{equation}
where $H$ is the Hamiltonian, $\zeta_i$ is Gaussian white noise with $\langle\zeta_i(t)\zeta_j(t')\rangle=2\delta_{ij}\delta(t-t')$, and $\epsilon v_i$ is an added term in the deterministic part of the dynamics that we keep general.
At $\epsilon=0$ the dynamics relaxes to the Gibbs distribution $P_0=e^{-H}/Z$, which for local $H$ is the Markov distribution for regions in Fig.\ref{fig:geometries}. 

To derive the perturbed probability $P_\epsilon$, we recall the Fokker--Planck equation
\begin{equation}
\label{Eq:stationary_fokker_planck}
 \sum_{i}\frac{\partial}{\partial \phi_i} \Big[ \Big( -\frac{\partial H}{\partial \phi_i} + \epsilon v_i - \frac{\partial}{\partial \phi_i}\Big)P\Big] = -\frac{\partial P}{\partial t}.
\end{equation}
For a stationary distribution, the right-hand side of Eq.~\eqref{Eq:stationary_fokker_planck} vanishes.
Write $P_\epsilon = P_0(1+\epsilon V) +O(\epsilon^2)$ with $P_0$ the Gibbs state that is the $\epsilon = 0$ stationary distribution.
Keeping the  terms of first order in $\epsilon$ gives
\begin{equation}
\begin{aligned}
0&=\sum_i\frac{\partial}{\partial\phi_i}\left[
-\frac{\partial H}{\partial\phi_i}P_0V+v_iP_0
-V\frac{\partial P_0}{\partial\phi_i} - P_0\frac{\partial V}{\partial\phi_i}\right]=\sum_i\frac{\partial}{\partial\phi_i}\left[
P_0\left(v_i-\frac{\partial V}{\partial\phi_i}\right)\right].
\end{aligned}
\end{equation}
Here we used $\partial P_0/\partial \phi_i = -(\partial H/\partial \phi_i) P_0$.  Expanding the remaining derivative once more gives
\begin{equation}
\label{Eq:steady_first_order}
\begin{aligned}
0&=P_0\sum_i\left[-v_i\frac{\partial H}{\partial\phi_i}
+\frac{\partial H}{\partial\phi_i}\frac{\partial V}{\partial\phi_i}
+\frac{\partial v_i}{\partial\phi_i}-\frac{\partial^2V}{\partial\phi_i^2}\right]=-P_0\left(\mathcal{L}^{(0)}V+\Sigma\right),
\end{aligned}
\end{equation}
where
\begin{equation}
\label{Eq:generator_and_source}
\mathcal{L}^{(0)}\equiv\sum_i\left[\frac{\partial^2}{\partial\phi_i^2}
-\frac{\partial H}{\partial\phi_i}\frac{\partial}{\partial\phi_i}\right],\quad
\Sigma\equiv\sum_i\left(v_i\frac{\partial H}{\partial\phi_i}-\frac{\partial v_i}{\partial\phi_i}\right).
\end{equation} 
In the continuum, one finds
\begin{equation}
\label{Eq:generator_continuum}
\mathcal{L}^{(0)}=\int d^dx\left[\frac{\delta^2}{\delta\phi(\mathbf{x})^2}
-\frac{\delta H}{\delta\phi(\mathbf{x})}\frac{\delta}{\delta\phi(\mathbf{x})}\right],\quad 
\Sigma[\phi]=\int d^dx\left[v(\mathbf{x})\frac{\delta H}{\delta\phi(\mathbf{x})}
-\frac{\delta v(\mathbf{x})}{\delta\phi(\mathbf{x})}\right],
\end{equation} 
with $\mathcal{L}^{(0)} V = - \Sigma$.
This implies  
\begin{equation}
\label{Eq:V_from_source}
V=(-\mathcal{L}^{(0)})^{-1}\Sigma=\int_0^\infty\!dt\;e^{t\mathcal{L}^{(0)}}\,\Sigma.
\end{equation}
Inserting this into Eq.~\eqref{Eq:perturbative_cmi} gives the CMI to order $\epsilon^2$, as written in Eq.~\eqref{Eq:cmi_susceptibility}. {Here $(-\mathcal{L}^{(0)})^{-1}$ should be understood as the pseudo-inverse on the subspace of zero-mean observables (in particular, $\langle V\rangle_0=0$).}

\section{Numerical details of the CMI scaling of the two-component model}
\label{app:two_component_exact}

We here present numerical details of the CMI scaling of the two-component model, i.e., Fig.\ref{fig:two_component_numerics} in the main text.
We will first derive the exact steady-state kernel, and then discuss how we UV regularize the kernel to calculate the CMI on a finite-size lattice.
For the reader's convenience, we repeat the Langevin equation from Eq.~\eqref{Eq:two_component}:
\begin{equation}
\begin{aligned}
\partial_t\Phi&=-(S+A)\Phi+\zeta,\qquad \Phi=(\phi,\psi)^T,\\
S&=-\begin{pmatrix}\partial_x^2+c\partial_y^2&0\\0&c\partial_x^2+\partial_y^2\end{pmatrix},
\qquad A=-\epsilon(\partial_x^3+\partial_y^3)X.
\end{aligned}
\end{equation}
Here $c>0$, $\langle\zeta_i(x,t)\zeta_j(x',t')\rangle=2\delta_{ij}\delta^2(x-x')\delta(t-t')$, and $X,Y,Z$ denote Pauli matrices acting on the two field components.
Since the dynamics is linear, the steady state is Gaussian, and its covariance $G=\langle\Phi\Phi^T\rangle=K^{-1}$ obeys the stationary Lyapunov equation
\begin{equation}
MG+GM^T=2I_2,\qquad M=S+A.
\end{equation} 
With the Fourier convention $\partial_j\mapsto ik_j$, the matrix $M=S+A$ for each nonzero momentum $\mathbf k=(k_x,k_y)$ is 
\begin{equation} 
\begin{aligned}
M(\mathbf k)&=\begin{pmatrix}a&iu\\iu&b\end{pmatrix},\quad 
a=k_x^2+ck_y^2,\ b=ck_x^2+k_y^2,\ u=\epsilon(k_x^3+k_y^3).
\end{aligned}
\end{equation}
Defining the momentum-space covariance through $\langle\Phi(\mathbf k)\Phi(\mathbf k')^T\rangle
=(2\pi)^2\delta^2(\mathbf k+\mathbf k')G(\mathbf k)$, we can write the corresponding  stationary Lyapunov equation as
\begin{equation}
\label{Eq:two_component_lyapunov_k}
M(\mathbf k)G(\mathbf k)+G(\mathbf k)M(\mathbf k)^\dagger=2I_2.
\end{equation}
Here $M(\mathbf k)^\dagger=M(-\mathbf k)^T$, so the odd-derivative term has opposite signs in $M(\mathbf k)$ and $M(\mathbf k)^\dagger$. 
Solving this $2\times2$ matrix equation gives
\begin{equation}
G(\mathbf k)=\frac{1}{(a+b)(ab+u^2)}
\begin{pmatrix}
b(a+b)+2u^2&iu(b-a)\\
-iu(b-a)&a(a+b)+2u^2
\end{pmatrix}.
\end{equation}
Inverting this covariance matrix, we obtain $K(\mathbf k)=G(\mathbf k)^{-1}$:
\begin{equation}
\label{Eq:two_component_K}
\begin{aligned}
K(\mathbf k)& =\begin{pmatrix}k_x^2+ck_y^2&0\\0&ck_x^2+k_y^2\end{pmatrix}
+
 \epsilon\frac{(c-1)\,(k_x^2-k_y^2)\,(k_x^3+k_y^3)\,
\big[\,2\epsilon(k_x^3+k_y^3)\,Z+(c+1)\,\mathbf k^2\,Y\,\big]}
{(c+1)^2\mathbf k^4+4\epsilon^2(k_x^3+k_y^3)^2}.
\end{aligned}
\end{equation}


We now discuss how we compute CMI from the exact
kernel in Eq.~\eqref{Eq:two_component_K}. 
We use a periodic $L\times L$ lattice with $L=128$ and $c=2$, in units of
the lattice spacing.  
Region $A$ is the site $(0,0)$ containing both fields,
so $l=1$;
$A\cup B$ is the square $\max(|x|,|y|)\leq l_B$ and $C$ is its complement. 
For the UV regularization, we make the replacements $k_j^2\mapsto 4 \sin^2(k_j/2),
k_x^3+k_y^3 \mapsto \sum_{j=x,y}(2\sin k_j-\sin 2k_j).$
Since the zero modes of the massless model do not have a normalizable
stationary distribution on a finite torus, we define the CMI
as the limit of an infinitesimal positive mass.
To avoid subtracting nearly equal entropies, we make use of the fact that region $A$ is small (it's a single site here) and write
\begin{equation}
\label{Eq:shared_gaussian_cmi}
I(A:C|B)=-\frac12\log\det\!\left[
I_{n_A}-K_A^{-1}K_{AC}K_C^{-1}K_{CA}\right],
\end{equation}
where $n_A = 2$ is the number of field variables in $A$ (in the long-range Ising model considered in App.\ref{app:lr_ising}, $n_A =1$). 
We construct $K_A$
and $K_{CA}$ from the inverse Fourier transform of the kernel and compute
$U\equiv K_C^{-1}K_{CA}$ by solving $K_CU=K_{CA}$
iteratively.
A similar method is used when computing CMI for the long-range Ising model in App.~\ref{app:lr_ising}.

\section{Long-range Ising model}
\label{app:lr_ising}

The goal of this appendix is to provide more details about the CMI results for the long-range Ising model discussed in the main text.

\subsection{High-temperature expansion}
\label{app:lr_ising_high_temperature}
We here use a high-temperature expansion to verify that the CMI exponent in the geometry of Fig.~\ref{fig:geometries}(b) is $\eta = 2(1+\sigma)>2$. 
Recall that the Gibbs distribution of the long-range Ising model in $d=1$ is $P_\beta(s)\propto \exp(\beta\sum_{i<j}J_{ij}s_i s_j)$, with $J_{ij}=|i-j|^{-(1+\sigma)}$.
Since $\beta\ll1$, one can directly use the perturbative CMI formula in Eq.~\eqref{Eq:perturbative_cmi} with $\epsilon=\beta$, $P_0\propto I$, and (recall $P_\epsilon = P_0(1+\epsilon V)$)
\begin{equation}
V=\sum_{\substack{i<j\\i,j\in A\cup B\cup C}}J_{ij}s_i s_j.
\end{equation}
We now compute $V_X(s_X)\equiv\langle V\rangle_{0|X}(s_X)
=\sum_{s_{\bar X}}P_0(s_{\bar X}\mid s_X)\,V(s_X,s_{\bar X})$, 
which is needed to evaluate $V_\times=V-V_{AB}-V_{BC}+V_{B}$.
Since $P_0$ is a uniform product distribution, one has $\langle s_i s_j\rangle_{0|X}=s_i s_j$ for $i,j\in X$, and the conditional average vanishes otherwise.
It follows that $V_X=\sum_{i<j,\;i,j\in X}J_{ij}s_i s_j$ for $X=A\cup B,B\cup C,B$, and thus
\begin{equation}
V_\times=V-V_{AB}-V_{BC}+V_B
=\sum_{i\in A,\;j\in C}J_{ij}s_i s_j.
\end{equation}
We next compute $\langle V_\times^2\rangle_0$ by expanding the square. Since $A$ and $C$ are disjoint, independence under $P_0$ allows us to factor the four-spin average between these two regions:
\begin{equation}
\begin{aligned}
\langle V_\times^2\rangle_0
&=\sum_{i,k\in A}\sum_{j,l\in C}J_{ij}J_{kl}\langle s_i s_j s_k s_l\rangle_0
=\sum_{i,k\in A}\sum_{j,l\in C}J_{ij}J_{kl}\langle s_i s_k\rangle_0\langle s_j s_l\rangle_0
=\sum_{i\in A,\;j\in C}J_{ij}^{\,2},
\end{aligned}
\end{equation}
where we've used $\langle s_i s_k\rangle_0=\delta_{ik}$ in the last step.
Eq.~\eqref{Eq:perturbative_cmi} therefore yields
\begin{equation}
\label{Eq:lr_ising_high_temperature_cmi}
I(A:C|B)=\frac{\beta^2}{2}\langle V_\times^2\rangle_0+O(\beta^3)
=\frac{\beta^2}{2}\sum_{i\in A,\;j\in C}\frac{1}{|i-j|^{2(1+\sigma)}}+O(\beta^3).
\end{equation}
Now, let $A$ and $C$ each contain $n$ sites, separated by $n_B\gg n$ sites. Since there are $n^2$ cross pairs, each with separation $n_B+O(n)$, we have
\begin{equation}
\label{Eq:lr_ising_high_temperature_tail}
I(A:C|B)=\frac{\beta^2 n^2}{2n_B^{2(1+\sigma)}}
\left[1+O\!\left(\frac{n}{n_B}\right)\right]+O(\beta^3).
\end{equation}

\subsection{Critical CMI in one dimension}
\label{app:lr_ising_critical_1d}

We now compute the CMI directly at $\mu=0$ in the geometry of Fig.~\ref{fig:geometries}(b). We restrict ourselves to the Gaussian regime $0<\sigma<1/2$, with the UV regularization $K(q)=|2\sin(q/2)|^\sigma$ of $|q|^\sigma$, where $q$ is measured in lattice units.
